import 'dart:io'; import '../core/agent_models.dart'; import 'tool.dart';
class FileTool extends AgentTool {
  String get name=>'file'; Set<AgentPermission> requiredPermissions(Map<String,dynamic> p){final a=p['action']?.toString()??'read';return {'write','delete'}.contains(a)?{AgentPermission.localWrite}:{AgentPermission.readOnly};} String get description=>'إدارة ملفات مساحة المهمة.'; Map<String,dynamic> get parameters=>const {'action':'read | write | delete | list','path':'string','content':'string'};
  Future<StepResult> execute(Map<String,dynamic> p) async {final a=p['action']?.toString()??'read';final rel=p['path']?.toString()??'';if(rel.isEmpty||rel.contains('..')||rel.startsWith('/'))return StepResult.failure('مسار الملف يجب أن يكون نسبياً.');final root=Directory('/data/data/com.zion.os/files/agent-workspace');await root.create(recursive:true);final f=File(root.path+'/'+rel);try{switch(a){case 'read':if(!await f.exists())return StepResult.failure('الملف غير موجود.');return StepResult.success('تمت القراءة.',data:await f.readAsString());case 'write':await f.parent.create(recursive:true);await f.writeAsString(p['content']?.toString()??'');return StepResult.success('تم الحفظ.');case 'delete':if(!await f.exists())return StepResult.failure('الملف غير موجود.');await f.delete();return StepResult.success('تم الحذف.');case 'list':final d=Directory(f.path);if(!await d.exists())return StepResult.failure('المجلد غير موجود.');final items=await d.list().map((x)=>x.path.split('/').last).toList();return StepResult.success('تم السرد.',data:items);default:return StepResult.failure('إجراء file غير معروف.');}}catch(e){return StepResult.failure('فشل الملف: '+e.toString());}}
}
